import React, { useState, useEffect, useRef } from "react";
import Chart from 'chart.js/auto';

// --- DATOS INICIALES Y CONSTANTES (Sin cambios) ---
const initialExpenses = [
  { id: 1, date: "2023-08-10", category: "arriendo", amount: 1200000, description: "Arriendo oficina central" },
  { id: 2, date: "2023-08-05", category: "servicios", amount: 150000, description: "Pago de servicios básicos" },
];
const defaultCategories = ["arriendo", "servicios", "insumos", "sueldos", "imprevistos"];
const defaultPaymentMethods = ["efectivo", "transferencia", "tarjeta"];


function ExpensesPage() {
  // --- ESTADOS (Se añade uno para el total del mes y el ranking) ---
  const [expenses, setExpenses] = useState(() => JSON.parse(localStorage.getItem("expenses") || JSON.stringify(initialExpenses)));
  const [categories, setCategories] = useState(() => JSON.parse(localStorage.getItem("expenseCategories") || JSON.stringify(defaultCategories)));
  const [form, setForm] = useState({ date: "", category: "", amount: "", paymentMethod: "", description: "" });
  const [currentMonthTotal, setCurrentMonthTotal] = useState(0); // <-- NUEVO
  const [categoryRanking, setCategoryRanking] = useState([]); // <-- NUEVO
  // ...otros estados...
  const monthlyChartRef = useRef(null);
  const monthlyChartInstance = useRef(null);


  // --- LÓGICA DE useEffect (CON CÁLCULOS PARA KPI Y RANKING) ---
  useEffect(() => {
    // --- CÁLCULO PARA KPI Y RANKING (NUEVA LÓGICA) ---
    const now = new Date();
    const currentMonthKey = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    const total = expenses
      .filter(e => e.date?.startsWith(currentMonthKey))
      .reduce((sum, e) => sum + Number(e.amount), 0);
    setCurrentMonthTotal(total);

    const catTotals = expenses.reduce((acc, e) => {
        acc[e.category] = (acc[e.category] || 0) + Number(e.amount);
        return acc;
    }, {});
    const sortedCategories = Object.entries(catTotals)
      .sort(([, a], [, b]) => b - a)
      .map(([name, amount]) => ({ name, amount }));
    setCategoryRanking(sortedCategories);


    // --- GRÁFICO DE BARRAS MENSUAL (Mantenemos este por claridad) ---
    if (monthlyChartInstance.current) monthlyChartInstance.current.destroy();
    const monthLabels = Array.from({ length: 6 }, (_, i) => {
      const d = new Date(now.getFullYear(), now.getMonth() - 5 + i, 1);
      return d.toLocaleString('es-CL', { month: 'short' });
    });
    const monthlyTotals = Array.from({ length: 6 }, (_, i) => {
        const d = new Date(now.getFullYear(), now.getMonth() - 5 + i, 1);
        const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
        return expenses.filter(e => e.date?.startsWith(key)).reduce((sum, e) => sum + Number(e.amount), 0);
    });
    if (monthlyChartRef.current) {
        monthlyChartInstance.current = new Chart(monthlyChartRef.current, {
            type: 'bar',
            data: {
                labels: monthLabels,
                datasets: [{ data: monthlyTotals, backgroundColor: '#818cf8' }]
            },
            options: { plugins: { legend: { display: false } } }
        });
    }
  }, [expenses]);
  
  const handleSubmit = (e) => {
    e.preventDefault();
    setExpenses([...expenses, { ...form, id: Date.now() }]);
    setForm({ date: "", category: "", amount: "", paymentMethod: "", description: "" });
  };
  
  // --- RENDERIZADO DEL DISEÑO DASHBOARD ---
  return (
    <div className="bg-slate-100 min-h-screen">
      <div className="container mx-auto p-5">
        <h1 className="text-3xl font-bold text-slate-800 mb-6">Panel de Control de Gastos</h1>
        
        <main className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Columna principal */}
          <div className="lg:col-span-2 flex flex-col gap-6">
            {/* Widgets de KPIs y Gráficos */}
            <section className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {/* Widget KPI Gasto Mensual */}
                <div className="bg-white p-6 rounded-xl shadow">
                    <h2 className="text-lg font-semibold text-slate-500 mb-1">Gasto Total de este Mes</h2>
                    <p className="text-5xl font-bold text-slate-800">${currentMonthTotal.toLocaleString('es-CL')}</p>
                </div>
                 {/* Widget Ranking Categorías */}
                <div className="bg-white p-6 rounded-xl shadow">
                    <h2 className="text-lg font-semibold text-slate-500 mb-3">Ranking de Categorías</h2>
                    <ul className="space-y-2">
                        {categoryRanking.slice(0, 4).map(cat => (
                           <li key={cat.name} className="flex justify-between items-center text-sm">
                               <span className="font-medium text-slate-700 capitalize">{cat.name}</span>
                               <span className="font-bold text-slate-500">${cat.amount.toLocaleString('es-CL')}</span>
                           </li> 
                        ))}
                    </ul>
                </div>
            </section>
            <section className="bg-white p-6 rounded-xl shadow">
              <h2 className="text-xl font-semibold text-slate-700 mb-4">Historial de Gastos Mensuales</h2>
              <canvas ref={monthlyChartRef}></canvas>
            </section>
          </div>

          {/* Columna lateral (Formulario) */}
          <aside className="lg:col-span-1">
            <div className="bg-white p-6 rounded-xl shadow sticky top-6">
                <h2 className="text-xl font-semibold text-slate-800 mb-4">Añadir Gasto</h2>
                <form onSubmit={handleSubmit} className="space-y-4">
                    <input type="date" name="date" value={form.date} onChange={(e) => setForm({...form, date: e.target.value})} className="w-full bg-slate-50 border-slate-200 border rounded-lg p-3" required />
                    <select name="category" value={form.category} onChange={(e) => setForm({...form, category: e.target.value})} className="w-full bg-slate-50 border-slate-200 border rounded-lg p-3" required>
                      <option value="">Categoría</option>
                      {categories.map(c=><option key={c} value={c}>{c.charAt(0).toUpperCase() + c.slice(1)}</option>)}
                    </select>
                    <input type="number" name="amount" value={form.amount} placeholder="Monto" onChange={(e) => setForm({...form, amount: e.target.value})} className="w-full bg-slate-50 border-slate-200 border rounded-lg p-3" required />
                    <input type="text" name="description" value={form.description} placeholder="Descripción" onChange={(e) => setForm({...form, description: e.target.value})} className="w-full bg-slate-50 border-slate-200 border rounded-lg p-3" />
                    <button type="submit" className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 rounded-lg">Guardar Gasto</button>
                </form>
            </div>
          </aside>
        </main>
      </div>
    </div>
  );
}

export default ExpensesPage;
